# Python: Agent side - sign outgoing requests import hashlib, time, secrets, base64 from nacl.signing import SigningKey
# target is the origin-form request target: path, plus "?"+query if a # query is present (Section 3.1). Percent-encoding is preserved as sent. def sign_request(method, target, body, domain, selector, key): # Normalize per Section 3.1: d/s/n lowercase, method uppercase. domain, selector = domain.lower(), selector.lower() method = method.upper() t = str(int(time.time())) # canonical decimal, no zero-pad n = secrets.token_hex(8) # 16 lowercase hex chars body_hash = hashlib.sha256(body).hexdigest() signing_input = f"{domain}
{selector}
{t}
{n}
" signing_input += f"{method}
{target}
{body_hash}
" sig = key.sign(signing_input.encode()).signature sig_b64 = base64.b64encode(sig).decode().rstrip("=") return { "ApertoID-Signature": f"d={domain}; s={selector}; t={t}; n={n}; sig={sig_b64}" }
# Python: Verifier side - verify incoming requests def verify_request(request): header = request.headers.get("ApertoID-Signature") if not header: return "unsigned" tags = parse_tags(header) # extract d, s, t, n, sig # ... check timestamp, nonce (read only), DNS lookup, then: # Reconstruct the origin-form target = path [ "?" query ] exactly as # sent; request.path alone DROPS the query and would break the sig. target = request.path if request.query_string: target += "?" + request.query_string body_hash = hashlib.sha256(request.body).hexdigest() signing_input = ( f"{tags['d'].lower()}
{tags['s'].lower()}
" f"{tags['t']}
{tags['n'].lower()}
" f"{request.method.upper()}
{target}
{body_hash}
" ) pubkey = get_apertoid_pubkey(tags['d'], tags['s']) # DNS ok = verify_ed25519(pubkey, signing_input, tags['sig']) # Only now, after the signature verifies, insert n= into the nonce # cache (Section 4, step 9a). return ok
